// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property() public {
        // The general rule: owner() should return address(0)
        // because the reference contract returns the stored _owner which is set to address(this) in constructor.
        // The buggy version always returns address(0).
        // We assert that owner() equals address(0).
        assertTrue(c.owner() == address(0));
    }
}

