pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant INITIAL_OWNER = address(this);

    function setUp() public { 
        c = new C(address(this), address(this)); 
    }

    function testFuzz_property(address rewardToken) public {
        // 1. Restrict to valid reward token (non-zero, not already added)
        vm.assume(rewardToken != address(0));

        // 2. Drive through addReward, which should not change owner
        c.addReward(rewardToken);

        // 3. General rule: the owner never changes after addReward
        assertTrue(c.owner() == INITIAL_OWNER);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        // 1. No restriction needed - the rule should hold for any address
        // 2. Drive c through its PUBLIC surface, ending in a call to `addReward(address)`
        address expectedOwner = address(this);

        // If rewardToken is the zero address, the call might revert in some contracts
        // but we can still test the property
        if (rewardToken == address(0)) {
            vm.assume(false); // skip zero address to avoid revert
        }

        c.addReward(rewardToken);

        // 3. exactly one assertTrue(<general rule>) reading c's PUBLIC getters / return values
        assertTrue(c.owner() == expectedOwner);
    }
}

