// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address user, address rewardToken, uint256 stakeAmount, uint256 rewardAmount) public {
        vm.assume(user != address(0) && user != address(this));
        vm.assume(rewardToken != address(0) && rewardToken != address(this));
        stakeAmount = bound(stakeAmount, 1, 1e30);
        rewardAmount = bound(rewardAmount, 1, 1e30);

        // First, add a reward token to the system
        c.addReward(rewardToken);

        // User stakes tokens
        deal(address(c.stakingToken()), user, stakeAmount);
        vm.prank(user);
        c.stake(stakeAmount);

        // Distribute reward
        deal(rewardToken, address(this), rewardAmount);
        c.notifyRewardAmount(rewardToken, rewardAmount);

        // Advance time to make reward claimable
        vm.warp(block.timestamp + 7 days);

        // User claims reward (this triggers updateReward and payout)
        vm.prank(user);
        c.getRewards(user);

        // Now add another reward token (or same token again - but addReward prevents duplicates, so we use a different token)
        address rewardToken2 = address(uint160(uint256(keccak256(abi.encode(rewardToken, 1)))));
        vm.assume(rewardToken2 != address(0) && rewardToken2 != address(this) && rewardToken2 != rewardToken);

        c.addReward(rewardToken2);

        // The invariant: after addReward, the claimableRewards for any user and the new token should be zero
        uint256 claimable = c.claimableRewards(user, rewardToken2);
        assertTrue(claimable == 0, "claimableRewards should be zero after addReward");
    }
}

