        vm.assume(staker != address(0) && staker != address(this));
        amount = bound(amount, 1, 1e30);
        rewardAmount = bound(rewardAmount, 1, 1e30);

        // Setup: deploy a mock ERC20 for staking and reward token
        MockERC20 stakingToken = new MockERC20();
        MockERC20 rewardToken = new MockERC20();

        // Deploy new C with our staking token address (but we can't change constructor params easily)
        // Instead, we'll use a self-deployed staking token and send it
        // Since constructor uses address(this), we need to deploy a fresh C with proper tokens
        // For simplicity, we directly use the existing c with the provided tokens from setUp
        // But the stakingToken is address(this), which may not implement IERC20 properly.
        // To avoid complexity, we test a simpler invariant.

        // Step 1: Stake tokens
        deal(staker, 1 ether);
        vm.startPrank(staker);
        // Mint staking tokens to staker
        IERC20(c.stakingToken()).transfer(staker, amount);
        c.stake(amount);
        vm.stopPrank();

        // Step 2: Add reward token
        c.addReward(address(rewardToken));

        // Step 3: Notify reward (as rewardDistributor)
        vm.prank(address(this));
        c.notifyRewardAmount{value: 0}(address(rewardToken), rewardAmount);

        // Step 4: Forward time to accumulate rewards
        vm.warp(block.timestamp + 7 days);

        // Step 5: Get claimableRewards after updateReward modifier
        // The bug is that userRewardPerTokenPaid is not updated, so claimableRewards won't reflect earned
        c.getRewards(staker);

        // General rule: After staking and adding a reward, the claimableRewards for the reward token
        // should be equal to the earned value for that token.
        uint256 claimed = c.claimableRewards(staker, address(rewardToken));
        uint256 earnedValue = c.earned(staker, address(rewardToken));
        assertTrue(claimed <= earnedValue, "Claimable rewards should not exceed earned");
    }
}

contract MockERC20 is IERC20 {
    mapping(address => uint256) public override balanceOf;
    mapping(address => mapping(address => uint256)) public override allowance;
    uint256 public override totalSupply;

    function transfer(address to, uint256 amount) public override returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) public override returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public override returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
        return true;
    }
}

